#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
using namespace std;

int main(){
vector<double> forecast={0.02,-0.01,0.03},realized={0.01,0.02,0.04};
double mse=0,tradingGross=0,turnover=0,previous=0;
for(int t=0;t<int(forecast.size());t++){
    mse+=pow(forecast[t]-realized[t],2)/forecast.size();
    double position=forecast[t]>0?1:-1;
    tradingGross+=position*realized[t];
    turnover+=fabs(position-previous);previous=position;
}
double netReturn=tradingGross-0.0005*turnover;
cout<<"prediction MSE "<<mse<<" trading net "<<netReturn<<"\n";
return 0;
}

