#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
using namespace std;

int main(){
double weight=1.0,m=0,v=0,rate=0.01,beta1=0.9,beta2=0.999;
for(int t=1;t<=8;t++){
    double gradient=2*(weight-0.3);
    m=beta1*m+(1-beta1)*gradient;
    v=beta2*v+(1-beta2)*gradient*gradient;
    double correctedM=m/(1-pow(beta1,t));
    double correctedV=v/(1-pow(beta2,t));
    weight-=rate*correctedM/(sqrt(correctedV)+1e-8);
    cout<<t<<" "<<weight<<"\n";
}
return 0;
}

