#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <random>
using namespace std;

int main(){
vector<double> x={-2,-1,1,2},label={0,0,1,1};
double beta=0;
for(int iteration=0;iteration<8;iteration++){
    double gradient=0,hessian=0;
    for(int i=0;i<int(x.size());i++){
        double p=1/(1+exp(-beta*x[i]));
        gradient+=(p-label[i])*x[i];
        hessian+=p*(1-p)*x[i]*x[i];
    }
    if(hessian<1e-10)break;
    beta-=gradient/hessian;
}
cout<<"IRLS final slope "<<beta<<"\n";
return 0;
}

