int main(){
vector<double> a={1,2,3,4,5},b={1.1,2.05,2.96,4.02,5.08};
double ma=0,mb=0,saa=0,sbb=0,sab=0;
for(int i=0;i<int(a.size());i++){ma+=a[i]/a.size();mb+=b[i]/b.size();}
for(int i=0;i<int(a.size());i++){
    double x=a[i]-ma,y=b[i]-mb;
    saa+=x*x;sbb+=y*y;sab+=x*y;
}
